/**
 * Embeds the SQL migrations generated by drizzle-kit into a TypeScript module so the runtime
 * migrator never depends on reading files from disk (serverless bundles do not ship the
 * drizzle/ folder). Run automatically after `pnpm db:generate`.
 */
import { createHash } from "node:crypto";
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = process.cwd();
const dir = join(root, "drizzle");
const journal = JSON.parse(readFileSync(join(dir, "meta", "_journal.json"), "utf8")) as {
  entries: Array<{ idx: number; tag: string; when: number }>;
};

const files = new Set(readdirSync(dir).filter((f) => f.endsWith(".sql")));
const entries = journal.entries
  .sort((a, b) => a.idx - b.idx)
  .map((e) => {
    const file = `${e.tag}.sql`;
    if (!files.has(file)) throw new Error(`Migration file missing for journal entry ${e.tag}`);
    const sql = readFileSync(join(dir, file), "utf8");
    const statements = sql
      .split("--> statement-breakpoint")
      .map((s) => s.trim())
      .filter((s) => s.length > 0);
    return { idx: e.idx, tag: e.tag, hash: createHash("sha256").update(sql).digest("hex"), statements };
  });

const out = `// GENERATED FILE — do not edit. Run \`pnpm db:generate\` to regenerate.
// Embedded copies of the SQL migrations under ./drizzle so the app can migrate itself at startup
// on any host without filesystem access to the migrations folder.
export interface EmbeddedMigration {
  idx: number;
  tag: string;
  hash: string;
  statements: string[];
}

export const EMBEDDED_MIGRATIONS: EmbeddedMigration[] = ${JSON.stringify(entries, null, 2)};
`;

writeFileSync(join(root, "src", "server", "db", "migrations.generated.ts"), out);
console.log(`Embedded ${entries.length} migration(s).`);
